<script>
  import { createEventDispatcher } from 'svelte';
  import { t } from './i18n.js';
  export let layout;
  export let images = [];
  export let editable = false;
  const dispatch = createEventDispatcher();
  let selected = -1, board, drag, backgroundUrl = '';
  $: item = layout?.items?.[selected];
  $: backgroundUrl = layout?.backgroundImage != null ? images[layout.backgroundImage] : '';
  const snapPoints = [0, 90, 180, 270];
  function normalizeRotation(value) { return ((value % 360) + 360) % 360; }
  function snapRotation(value) {
    const angle = normalizeRotation(value);
    const closest = snapPoints.reduce((best, point) => {
      const difference = Math.min(Math.abs(angle - point), 360 - Math.abs(angle - point));
      return difference < best.difference ? { point, difference } : best;
    }, { point: angle, difference: Infinity });
    return closest.difference <= 7 ? closest.point : angle;
  }
  $: if (layout?.version === 1 && layout.items.some(entry => !Number.isFinite(entry.x) || !Number.isFinite(entry.y))) {
    layout = { ...layout, items: layout.items.map(entry => ({ ...entry, x: Number.isFinite(entry.x) ? entry.x : 10, y: Number.isFinite(entry.y) ? entry.y : 10 })) };
  }
  function addText() { layout = {...layout, items:[...layout.items,{type:'text',text:'',x:10,y:10,width:40,rotation:0,font:'sans-serif',size:24,color:'#17231c'}]}; selected=layout.items.length-1; }
  function update(key,value) { layout={...layout,items:layout.items.map((v,i)=>i===selected?{...v,[key]:value}:v)}; }
  function remove() { if(item?.type==='image') dispatch('removeimage',item.image); else layout={...layout,items:layout.items.filter((_,i)=>i!==selected)}; selected=-1; }
  function duplicate() { if(!item||layout.items.length>=24)return; layout={...layout,items:[...layout.items,{...item,x:Math.min(90,item.x+5),y:Math.min(90,item.y+5)}]}; selected=layout.items.length-1; }
  function handleStart(e,mode) { e.stopPropagation(); const r=board.getBoundingClientRect(); drag={mode,x:e.clientX,y:e.clientY,width:r.width,height:r.height,rotation:normalizeRotation(item.rotation),size:item.size,itemWidth:item.width}; e.currentTarget.setPointerCapture(e.pointerId); }
  function handleMove(e) { if(!drag||selected<0)return; if(drag.mode==='rotate') update('rotation',normalizeRotation(drag.rotation+(e.clientX-drag.x)*.7)); else { const delta=(e.clientX-drag.x)/drag.width*100; if(item.type==='text')update('size',Math.max(10,Math.min(72,drag.size+delta))); update('width',Math.max(5,Math.min(100,drag.itemWidth+delta))); } }
  function finishDrag() { if (drag?.mode === 'rotate' && item) update('rotation', snapRotation(item.rotation)); drag = null; }
  function start(e,i) { if(!editable||e.button!==0)return; selected=i; const r=board.getBoundingClientRect(); drag={x:e.clientX,y:e.clientY,left:layout.items[i].x,top:layout.items[i].y,width:r.width,height:r.height}; e.currentTarget.setPointerCapture(e.pointerId); e.preventDefault(); }
  function move(e) { if(!drag||drag.mode||selected<0)return; update('x',Math.max(0,Math.min(100,drag.left+(e.clientX-drag.x)/drag.width*100))); update('y',Math.max(0,Math.min(100,drag.top+(e.clientY-drag.y)/drag.height*100))); }
</script>
{#if editable}<div class="studio">
  <aside class="tools"><div class="eyebrow">{$t('画布工具')}</div><button class="tool active" type="button" on:click={addText}>T <span>{$t('添加文字')}</span></button><button class="tool" type="button" on:click={() => dispatch('addimage')}>▧ <span>{$t('添加图片')}</span></button><button class="tool" type="button" on:click={() => dispatch('addbackgroundimage')}>▧ <span>{$t('设置背景图')}</span></button>{#if layout.backgroundImage != null}<button class="tool" type="button" on:click={() => dispatch('removeimage', layout.backgroundImage)}>× <span>{$t('移除背景图')}</span></button>{/if}<div class="tip">{$t('拖动元素调整位置，松开旋转控件时角度会吸附到附近的直角方向。')}</div></aside>
  <section class="workspace"><div class="stage-head"><span>{$t('编辑画布')}</span><span>{$t('点击元素进行编辑')}</span></div>
<div class="board" class:editing={editable} class:has-background={!!backgroundUrl} style={backgroundUrl ? `background-image:url(${backgroundUrl})` : ''} bind:this={board}>
  {#each layout?.items || [] as entry, i}<div class="element" class:selected={editable&&selected===i} role="button" tabindex={editable?0:-1} aria-label={editable?$t('选择画布元素'):undefined} on:click={()=>editable&&(selected=i)} on:keydown={(e)=>{if(editable&&(e.key==='Enter'||e.key===' '))selected=i;}} on:pointerdown={(e)=>start(e,i)} on:pointermove={move} on:pointerup={()=>drag=null} on:pointercancel={()=>drag=null} style={`left:${entry.x}%;top:${entry.y}%;width:${entry.width}%;transform:rotate(${entry.rotation}deg)`}>{#if entry.type==='text'}<div class="text" style={`font-family:${entry.font};font-size:${entry.size/6}cqw;color:${entry.color||'#17231c'}`}>{entry.text|| (editable?$t('文字'):'')}</div>{:else if images[entry.image]}<img src={images[entry.image]} alt="" draggable="false"/>{/if}{#if editable&&selected===i}<button class="corner delete" type="button" title={$t('删除元素')} on:pointerdown|stopPropagation on:click|stopPropagation={remove}>×</button><button class="corner copy" type="button" title={$t('复制元素')} on:pointerdown|stopPropagation on:click|stopPropagation={duplicate}>⧉</button><button class="corner rotate" type="button" title={$t('旋转')} on:pointerdown={(e)=>handleStart(e,'rotate')} on:pointermove|stopPropagation={handleMove} on:pointerup|stopPropagation={finishDrag}>↻</button><button class="corner resize" type="button" title={$t('缩放')} on:pointerdown={(e)=>handleStart(e,'resize')} on:pointermove|stopPropagation={handleMove} on:pointerup|stopPropagation={finishDrag}>↗</button>{/if}</div>{/each}
  {#if editable&&layout.items.length===0}<div class="empty"><span>＋</span>{$t('从左侧添加文字或图片')}</div>{/if}
</div>
<div class="inspector"><div class="inspector-head"><strong>{$t('元素属性')}</strong>{#if item}<button type="button" on:click={remove}>{$t('删除元素')}</button>{/if}</div>
  {#if item}<div class="fields">{#if item.type==='text'}<label class="wide">{$t('文字')}<textarea value={item.text} maxlength="280" on:input={e=>update('text',e.currentTarget.value)}></textarea></label><label>{$t('字体')}<select value={item.font} on:change={e=>update('font',e.currentTarget.value)}><option value="sans-serif">{$t('无衬线')}</option><option value="serif">{$t('衬线')}</option><option value="monospace">{$t('等宽')}</option></select></label><label>{$t('文字颜色')}<input type="color" value={item.color||'#17231c'} on:input={e=>update('color',e.currentTarget.value)}/></label><label>{$t('字号')}<input type="number" min="10" max="72" value={item.size} on:change={e=>update('size',Math.max(10,Math.min(72,+e.currentTarget.value||10)))}/></label>{/if}<label>{$t('宽度')}<input type="number" min="5" max="100" value={item.width} on:change={e=>update('width',Math.max(5,Math.min(100,+e.currentTarget.value||5)))}/></label><label>{$t('旋转')}<input type="number" min="0" max="360" value={normalizeRotation(item.rotation)} on:change={e=>update('rotation',snapRotation(+e.currentTarget.value||0))}/></label><label>X<input type="number" min="0" max="100" value={Math.round(item.x)} on:change={e=>update('x',Math.max(0,Math.min(100,+e.currentTarget.value||0)))}/></label><label>Y<input type="number" min="0" max="100" value={Math.round(item.y)} on:change={e=>update('y',Math.max(0,Math.min(100,+e.currentTarget.value||0)))}/></label></div>{:else}<p>{$t('选择一个画布元素以调整属性。')}</p>{/if}</div>
  </section>
</div>{/if}
<style>
 .studio{display:grid;grid-template-columns:160px minmax(0,1fr);min-height:520px;border:1px solid var(--border-subtle);border-radius:12px;overflow:hidden;background:var(--surface)}.tools{padding:16px 12px;border-right:1px solid var(--border-subtle);background:var(--surface-elevated)}.eyebrow,.stage-head,.inspector-head{font-size:12px;color:var(--ink-muted);letter-spacing:.04em}.eyebrow{padding:4px 8px 12px}.tool{display:flex;width:100%;align-items:center;gap:12px;margin:4px 0;padding:12px;border:1px solid transparent;border-radius:8px;background:transparent;color:var(--ink-secondary);text-align:left;cursor:pointer}.tool:first-of-type{font-size:18px}.tool span{font-size:13px}.tool:hover,.tool.active{background:var(--accent-soft);color:var(--accent-deep)}.tip{margin:18px 7px;color:var(--ink-subtle);font-size:12px;line-height:1.6}.workspace{display:flex;flex-direction:column;min-width:0;padding:18px;background:var(--surface-tint)}.stage-head{display:flex;justify-content:space-between;padding:0 2px 12px}.board{position:relative;width:100%;max-width:820px;aspect-ratio:3/2;align-self:center;overflow:hidden;container-type:inline-size;background-color:var(--surface-elevated);background-image:linear-gradient(45deg,#87908c12 25%,transparent 25%),linear-gradient(-45deg,#87908c12 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#87908c12 75%),linear-gradient(-45deg,transparent 75%,#87908c12 75%);background-size:24px 24px;background-position:0 0,0 12px,12px -12px,-12px 0;border:1px solid var(--border-default);box-shadow:0 8px 24px #0002}.board.has-background{background-repeat:no-repeat;background-position:center;background-size:cover}.editing .element{cursor:move;outline:1px dashed transparent;touch-action:none;position:absolute;transform-origin:center}.editing .element.selected{outline:2px solid #00a8e8;box-shadow:0 0 0 1px white}.corner{position:absolute;z-index:5;width:22px;height:22px;padding:0;border:1px solid #08a9df;border-radius:50%;background:#fff;color:#263238;line-height:20px;cursor:pointer;touch-action:none}.delete{top:-12px;left:-12px}.copy{top:-12px;right:-12px}.rotate{bottom:-12px;left:-12px}.resize{bottom:-12px;right:-12px}.element{position:absolute;transform-origin:center}.element img{display:block;width:100%;height:auto;pointer-events:none}.text{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.2}.empty{position:absolute;inset:0;display:grid;align-content:center;justify-items:center;gap:10px;color:var(--ink-subtle)}.empty span{font-size:28px}.inspector{grid-column:1/-1;padding:14px 18px;border-top:1px solid var(--border-subtle);background:var(--surface-elevated)}.inspector-head{display:flex;justify-content:space-between;align-items:center}.fields{display:flex;flex-wrap:wrap;align-items:end;gap:12px;margin-top:12px}.fields label{display:grid;gap:5px;color:var(--ink-muted);font-size:12px}.fields input,.fields select,.fields textarea{max-width:100%;padding:7px 9px}.fields input{width:82px}.fields .wide{flex:1 1 100%}.fields textarea{width:100%;min-height:56px}.inspector p{font-size:13px;color:var(--ink-subtle)}@media(max-width:620px){.studio{grid-template-columns:76px minmax(0,1fr)}.tools{padding:12px 6px}.tool{justify-content:center;padding:10px 4px}.tool span,.tip{display:none}.workspace{padding:10px}.fields{gap:8px}}
</style>
